#include <iostream>
#include <stdexcept>

int estimar(int piezas) {
    if (piezas < 0 || piezas > 10) {
        throw std::invalid_argument{"Cantidad fuera de 0 a 10"};
    }

    if (piezas == 0) {
        return 0;
    }

    return 3 + 2 * piezas;
}

int estimacion_doble(int piezas) {
    int minutos{estimar(piezas)};

    return minutos * 2;
}

int main() {
    try {
        std::cout << "Sesion:";

        int total{estimacion_doble(11)};

        std::cout << total;
    } catch (const std::invalid_argument& error) {
        std::cout << "Rechazado";
    }

    std::cout << ":Fin";

    return 0;
}

